head.script:
/* =====================================================================
 * TRUNG TÂM IN - THẺ TÊN (NAMECARD) & DANH BẠ ĐỂ BÀN (NAMEPLACE)
 *   Tạo lệnh in -> xem trước -> gửi máy in -> đánh dấu đã in
 *   Hàng đợi in, lịch sử in, quản lý mẫu in, mẫu mặc định theo sự kiện
 * API: /api/print, /api/print-templates, /api/events/{id}/print-templates (API_GUEST.md mục 8, 9)
 * ===================================================================== */
scwin.P = "pr";
/* =====================================================================
 * LỚP DÙNG CHUNG (giống các màn Hội trường / Sự kiện)
 *   - Phiên đăng nhập, quyền
 *   - Gọi API JSON bằng submission WebSquare (scwin.callApi)
 *   - Upload / tải file bằng XMLHttpRequest (submission không xử lý file nhị phân)
 * ===================================================================== */
scwin.API_BASE = "http://localhost:8081";
scwin.KEY = { TOKEN: "ssc_token", USER: "ssc_user", PERMS: "ssc_permissions", MENUS: "ssc_menus" };
scwin.LOGIN_PAGE = "/authPage/LoginPage.xml";
scwin.CTX = window.location.pathname.replace(/\/websquare\/websquare\.html.*$/, "");
scwin.SBM_TIMEOUT = 60000;
scwin.sbmQueue = {};
scwin.sbmJob = {};
scwin.toastTimer = null;

/* ---------- Tiện ích ---------- */
scwin.comp = function (id) { return $p.getComponentById(id); };
scwin.domOf = function (c) { return c ? (c.render || document.getElementById(c.id) || null) : null; };
scwin.show = function (c, v) { if (!c) return; if (v === false) c.addClass("is-hidden"); else c.removeClass("is-hidden"); };
scwin.toggleClass = function (c, cls, on) { if (!c) return; if (on) c.addClass(cls); else c.removeClass(cls); };
scwin.safeColor = function (c) { return /^#[0-9a-f]{3,8}$/i.test(String(c || "")) ? c : "#63746b"; };
scwin.trim = function (v) { return v == null ? "" : String(v).replace(/^\s+|\s+$/g, ""); };
scwin.dash = function (v) { return (v == null || scwin.trim(v) === "") ? "—" : String(v); };
scwin.pad = function (n) { return n < 10 ? "0" + n : String(n); };
scwin.clamp = function (v, a, b) { v = Number(v) || 0; a = a == null ? 0 : a; b = b == null ? 100 : b; return Math.max(a, Math.min(b, v)); };
scwin.hasOwn = function (o, k) { return o != null && Object.prototype.hasOwnProperty.call(o, k); };
scwin.fmtNumber = function (n) { return (n == null || n === "" || isNaN(Number(n))) ? "—" : Number(n).toLocaleString("vi-VN"); };
scwin.fmtRate = function (r) { return (Math.round((Number(r) || 0) * 10) / 10).toLocaleString("vi-VN") + "%"; };
scwin.fmtDate = function (s) { if (!s) return ""; var p = String(s).substring(0, 10).split("-"); return p.length === 3 ? p[2] + "/" + p[1] + "/" + p[0] : String(s); };
scwin.fmtTime = function (s) { return s ? String(s).substring(0, 5) : ""; };
scwin.fmtDateTime = function (iso) {
    if (!iso) return "—";
    var d = new Date(iso);
    if (isNaN(d.getTime())) return String(iso);
    return scwin.pad(d.getDate()) + "/" + scwin.pad(d.getMonth() + 1) + "/" + d.getFullYear() + " " + scwin.pad(d.getHours()) + ":" + scwin.pad(d.getMinutes());
};
scwin.fmtClock = function (iso) {
    var d = iso ? new Date(iso) : new Date();
    if (isNaN(d.getTime())) d = new Date();
    return scwin.pad(d.getHours()) + ":" + scwin.pad(d.getMinutes()) + ":" + scwin.pad(d.getSeconds());
};
scwin.fmtSize = function (b) { return b >= 1048576 ? (b / 1048576).toFixed(1) + " MB" : Math.max(1, Math.round(b / 1024)) + " KB"; };
/** Tham số mảng được nối bằng dấu phẩy (backend nhận cả "A,B" lẫn lặp tham số). */
scwin.buildQuery = function (p) {
    var out = [];
    for (var k in p) {
        if (!p.hasOwnProperty(k)) continue;
        var v = p[k];
        if (Array.isArray(v)) { if (!v.length) continue; v = v.join(","); }
        if (v === null || v === undefined || v === "") continue;
        out.push(encodeURIComponent(k) + "=" + encodeURIComponent(v));
    }
    return out.join("&");
};
scwin.getQueryParam = function (name) {
    var m = new RegExp("[?&]" + name + "=([^&#]*)").exec(window.location.search);
    return m ? decodeURIComponent(m[1].replace(/\+/g, " ")) : "";
};
scwin.pageUrl = function (path, params) {
    var q = params ? scwin.buildQuery(params) : "";
    return scwin.CTX + "/websquare/websquare.html?w2xPath=" + scwin.CTX + path + (q ? "&" + q : "");
};
scwin.escHtml = function (s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); };
scwin.el = function (tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
scwin.clearEl = function (el) { if (el) while (el.firstChild) el.removeChild(el.firstChild); };
scwin.fitGrid = function (grid, rows, rowH, maxRows) {
    var n = maxRows ? Math.min(rows, maxRows) : rows;
    grid.setStyle("height", (rows ? 42 + n * (rowH || 46) + 2 : 0) + "px");
    scwin.show(grid, rows > 0);
};
scwin.isTrue = function (v) { return v === true || v === "true" || v === 1 || v === "1"; };

/* ---------- Phiên đăng nhập & quyền ---------- */
scwin.storeGet = function (k) { try { return window.localStorage.getItem(k) || window.sessionStorage.getItem(k) || ""; } catch (e) { return ""; } };
scwin.parseJSON = function (t) { if (!t || typeof t !== "string") return null; try { return JSON.parse(t); } catch (e) { return null; } };
scwin.getToken = function () { return String(scwin.storeGet(scwin.KEY.TOKEN)).replace(/^Bearer\s+/i, ""); };
scwin.getPerms = function () { return scwin.parseJSON(scwin.storeGet(scwin.KEY.PERMS)) || []; };
scwin.getUser = function () { return scwin.parseJSON(scwin.storeGet(scwin.KEY.USER)) || {}; };
/** Header chưa kịp lưu quyền (lần đầu vào trang) thì tạm cho phép; backend vẫn chặn bằng 403. */
scwin.can = function (code) { var p = scwin.getPerms(); return !p.length || p.indexOf(code) >= 0; };
scwin.canAny = function (codes) { for (var i = 0; i < codes.length; i++) if (scwin.can(codes[i])) return true; return false; };
scwin.goLogin = function () {
    if (scwin._redirecting) return;
    scwin._redirecting = true;
    for (var k in scwin.KEY) {
        if (!scwin.KEY.hasOwnProperty(k)) continue;
        try { window.localStorage.removeItem(scwin.KEY[k]); window.sessionStorage.removeItem(scwin.KEY[k]); } catch (e) { }
    }
    window.location.href = scwin.pageUrl(scwin.LOGIN_PAGE);
};

/* ---------- Lỗi ---------- */
scwin.defaultMessage = function (status) {
    if (status === 0) return "Không kết nối được máy chủ. Kiểm tra mạng hoặc backend (" + scwin.API_BASE + ").";
    if (status === 401) return "Phiên đăng nhập đã hết hạn. Hãy đăng nhập lại.";
    if (status === 403) return "Tài khoản của bạn chưa được cấp quyền cho thao tác này.";
    if (status === 404) return "Không tìm thấy dữ liệu, hoặc dữ liệu nằm ngoài phạm vi bạn được xem.";
    if (status >= 500) return "Máy chủ đang gặp sự cố. Thử lại sau ít phút.";
    return "Yêu cầu không thành công (HTTP " + status + ").";
};
scwin.authHeader = function (accept) {
    var h = { "Accept": accept || "application/json" };
    var t = scwin.getToken();
    if (t) h["Authorization"] = "Bearer " + t;
    return h;
};
/** Chuẩn hóa lỗi: { status, code, message, data }. 401 thì đưa về trang đăng nhập. */
scwin.buildError = function (status, json) {
    var err = {
        status: status || 0,
        code: (json && json.code) || (status ? "HTTP_" + status : "NETWORK_ERROR"),
        message: (json && json.message) || scwin.defaultMessage(status || 0),
        data: json ? json.data : null
    };
    if (status === 401) {
        err.message = scwin.defaultMessage(401);
        scwin.toast(err.message + " Đang chuyển về trang đăng nhập…", "error");
        setTimeout(scwin.goLogin, 1500);
    }
    return err;
};

/* ---------- Submission ----------
 *   scwin.callApi("sbm_xxx", { url: "...", body: {...} }) -> Promise<data>
 *   Mỗi submission có hàng đợi riêng nên gọi chồng nhau không bị trả nhầm kết quả.
 */
scwin.callApi = function (sbmId, opts) {
    return new Promise(function (resolve, reject) {
        if (!scwin.sbmQueue[sbmId]) scwin.sbmQueue[sbmId] = [];
        scwin.sbmQueue[sbmId].push({ opts: opts || {}, resolve: resolve, reject: reject });
        scwin.sbmNext(sbmId);
    });
};
scwin.sbmNext = function (sbmId) {
    if (scwin.sbmJob[sbmId]) return;
    var q = scwin.sbmQueue[sbmId];
    if (!q || !q.length) return;
    var job = q.shift();
    scwin.sbmJob[sbmId] = job;
    var sbm = $p.getSubmission(sbmId);
    if (!sbm) { scwin.sbmSettle(sbmId, null, { status: 0, code: "SUBMISSION_NOT_FOUND", message: "Chưa khai báo submission " + sbmId + "." }); return; }
    sbm.action = job.opts.url;
    sbm.requestHeader = scwin.authHeader();
    job.timer = setTimeout(function () {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "TIMEOUT", message: "Máy chủ phản hồi quá lâu. Thử lại sau." });
    }, scwin.SBM_TIMEOUT);
    try {
        if (job.opts.body !== undefined) $p.executeSubmission(sbmId, job.opts.body);
        else $p.executeSubmission(sbmId);
    } catch (ex) {
        scwin.sbmSettle(sbmId, null, { status: 0, code: "SUBMISSION_ERROR", message: (ex && ex.message) || String(ex) });
    }
};
scwin.sbmSettle = function (sbmId, data, err) {
    var job = scwin.sbmJob[sbmId];
    if (!job) return;
    clearTimeout(job.timer);
    scwin.sbmJob[sbmId] = null;
    if (err) job.reject(err); else job.resolve(data);
    scwin.sbmNext(sbmId);
};
scwin.readResponse = function (e) {
    if (!e) return null;
    if (e.responseJSON && typeof e.responseJSON === "object") return e.responseJSON;
    return scwin.parseJSON(e.responseText) || scwin.parseJSON(e.responseBody);
};
scwin.onSbmDone = function (sbmId, e) {
    var json = scwin.readResponse(e);
    if (json && json.success === false) { scwin.sbmSettle(sbmId, null, scwin.buildError((e && e.responseStatusCode) || 200, json)); return; }
    scwin.sbmSettle(sbmId, scwin.hasOwn(json, "data") ? json.data : json, null);
};
scwin.onSbmError = function (sbmId, e) {
    var status = (e && (e.responseStatusCode || e.status)) || 0;
    scwin.sbmSettle(sbmId, null, scwin.buildError(status, scwin.readResponse(e)));
};

/* ---------- XMLHttpRequest: upload multipart, nhận file ----------
 *   opts.body: object (gửi JSON) | FormData (multipart)
 *   opts.responseType: "json" (mặc định) | "blob" -> resolve { blob, name, type, headers }
 */
scwin.xhr = function (method, url, opts) {
    opts = opts || {};
    return new Promise(function (resolve, reject) {
        var x = new XMLHttpRequest();
        x.open(method, url);
        var h = scwin.authHeader(opts.responseType === "blob" ? "*/*" : "application/json");
        for (var k in h) if (h.hasOwnProperty(k)) x.setRequestHeader(k, h[k]);
        var body = null;
        if (typeof FormData !== "undefined" && opts.body instanceof FormData) body = opts.body;
        else if (opts.body !== undefined && opts.body !== null) { x.setRequestHeader("Content-Type", "application/json"); body = JSON.stringify(opts.body); }
        if (opts.responseType === "blob") x.responseType = "blob";
        if (opts.onProgress && x.upload) x.upload.onprogress = function (ev) { if (ev.lengthComputable) opts.onProgress(Math.round(ev.loaded * 100 / ev.total)); };
        x.onload = function () {
            var ok = x.status >= 200 && x.status < 300;
            if (opts.responseType === "blob") {
                var type = x.getResponseHeader("Content-Type") || "";
                if (ok && type.indexOf("application/json") < 0) {
                    resolve({ blob: x.response, type: type, name: scwin.fileNameFrom(x.getResponseHeader("Content-Disposition")), xhr: x });
                    return;
                }
                scwin.readBlobJSON(x.response).then(function (json) { reject(scwin.buildError(ok ? 200 : x.status, json)); });
                return;
            }
            var json = scwin.parseJSON(x.responseText);
            if (ok && !(json && json.success === false)) resolve(scwin.hasOwn(json, "data") ? json.data : json);
            else reject(scwin.buildError(x.status, json));
        };
        x.onerror = function () { reject(scwin.buildError(0, null)); };
        x.send(body);
    });
};
scwin.readBlobJSON = function (blob) {
    return new Promise(function (resolve) {
        if (!blob || typeof FileReader === "undefined") { resolve(null); return; }
        var r = new FileReader();
        r.onload = function () { resolve(scwin.parseJSON(r.result)); };
        r.onerror = function () { resolve(null); };
        r.readAsText(blob);
    });
};
scwin.fileNameFrom = function (cd) {
    if (!cd) return "";
    var m = /filename\*=UTF-8''([^;]+)/i.exec(cd) || /filename="?([^";]+)"?/i.exec(cd);
    if (!m) return "";
    try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; }
};
scwin.saveBlob = function (blob, name) {
    var url = URL.createObjectURL(blob);
    var a = scwin.el("a", scwin.P + "-native-link");
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click();
    setTimeout(function () { URL.revokeObjectURL(url); if (a.parentNode) a.parentNode.removeChild(a); }, 1500);
};
/** Tải file (GET hoặc POST kèm body JSON) rồi lưu về máy. */
scwin.downloadFile = function (url, fallbackName, btn, method, body) {
    if (btn) btn.addClass("is-busy");
    return scwin.xhr(method || "GET", url, { responseType: "blob", body: body }).then(function (r) {
        scwin.saveBlob(r.blob, r.name || fallbackName);
        return r;
    }).catch(function (err) {
        scwin.toast(err.message, "error");
        throw err;
    }).then(function (r) { if (btn) btn.removeClass("is-busy"); return r; }, function () { if (btn) btn.removeClass("is-busy"); });
};
/** In file PDF: nạp vào iframe ẩn rồi mở hộp thoại in của trình duyệt. */
scwin.printBlob = function (blob) {
    return new Promise(function (resolve) {
        var old = document.getElementById("ssc-print-frame");
        if (old) old.parentNode.removeChild(old);
        var url = URL.createObjectURL(blob);
        var f = document.createElement("iframe");
        f.id = "ssc-print-frame";
        f.className = scwin.P + "-print-frame";
        f.src = url;
        f.onload = function () {
            setTimeout(function () {
                try { f.contentWindow.focus(); f.contentWindow.print(); }
                catch (e) { window.open(url, "_blank"); }
                resolve();
            }, 300);
        };
        document.body.appendChild(f);
    });
};

/* ---------- Thông báo ---------- */
scwin.toast = function (msg, type) {
    if (typeof tbx_toast === "undefined") return;
    clearTimeout(scwin.toastTimer);
    tbx_toast.setValue(msg || "");
    ["success", "error", "warning", "info"].forEach(function (c) { tbx_toast.removeClass(scwin.P + "-toast--" + c); });
    tbx_toast.addClass(scwin.P + "-toast--" + (type || "info"));
    tbx_toast.addClass("is-show");
    scwin.toastTimer = setTimeout(function () { tbx_toast.removeClass("is-show"); }, (type === "error" || type === "warning") ? 6500 : 3800);
};
scwin.tbx_toast_onclick = function () { tbx_toast.removeClass("is-show"); };
scwin.showWarnings = function (list) {
    if (!list || !list.length) return;
    setTimeout(function () { scwin.toast("Lưu ý: " + list.join(" "), "warning"); }, 1800);
};

/* ---------- Danh mục dùng chung: GET /api/guests/lookups ---------- */
scwin.lookups = { events: [], guestTypes: [], guestStatuses: [] };
scwin.typeMeta = function (code) {
    for (var i = 0; i < scwin.lookups.guestTypes.length; i++) if (scwin.lookups.guestTypes[i].code === code) return scwin.lookups.guestTypes[i];
    return { code: code, name: code || "—", color: "#9E9E9E" };
};
scwin.statusMeta = function (code) {
    for (var i = 0; i < scwin.lookups.guestStatuses.length; i++) if (scwin.lookups.guestStatuses[i].code === code) return scwin.lookups.guestStatuses[i];
    return { code: code, name: code || "—", color: "#9E9E9E" };
};
scwin.GUEST_TYPE_VN = { VIP: "VIP", SPEAKER: "Diễn giả", GUEST: "Khách mời", STAFF: "Nhân viên", PRESS: "Báo chí", OTHER: "Khác" };
scwin.GUEST_STATUS_VN = { INVITED: "Đã mời", CONFIRMED: "Đã xác nhận", CHECKED_IN: "Đã check-in", ABSENT: "Vắng mặt" };
scwin.typeName = function (code) { return scwin.GUEST_TYPE_VN[code] || scwin.typeMeta(code).name; };
scwin.statusName = function (code) { return scwin.GUEST_STATUS_VN[code] || scwin.statusMeta(code).name; };
scwin.eventLabel = function (e) { return e.eventCode + " - " + e.eventName + (e.startDate ? " (" + scwin.fmtDate(e.startDate) + ")" : ""); };


scwin.GUEST_API = scwin.API_BASE + "/api/guests";
scwin.PRINT_API = scwin.API_BASE + "/api/print";
scwin.TPL_API = scwin.API_BASE + "/api/print-templates";
scwin.EVENT_API = scwin.API_BASE + "/api/events";
scwin.DESIGNER_PAGE = "/printPage/TemplateDesigner.xml";
scwin.HANDOFF_KEY = "ssc_print_handoff";
scwin.PRINTER_KEY = "ssc_printer_name";
scwin.TYPE_VN = { NAMECARD: "Thẻ tên", NAMEPLACE: "Danh bạ để bàn" };
scwin.PAPER_VN = { A4: "A4", A5: "A5", BADGE_3X4: "Thẻ 3×4 inch", BADGE_4X6: "Thẻ 4×6 inch", CUSTOM: "Tùy chỉnh" };
scwin.JOB_VN = { QUEUED: "Chờ in", PRINTING: "Đang in", COMPLETED: "Đã in xong", FAILED: "In lỗi", CANCELLED: "Đã hủy" };
scwin.SOURCE_VN = { EVENT: "mẫu riêng của sự kiện", SYSTEM: "mẫu mặc định hệ thống", NONE: "chưa có mẫu" };

scwin.state = { tab: "new", printType: "NAMECARD", scope: "selected" };
scwin.picked = {};           // guestId -> { guestId, fullName }
scwin.pickedOrder = [];      // giữ thứ tự chọn
scwin.pick = { page: 0, totalPages: 0, totalElements: 0, items: [], seq: 0 };
scwin.templates = [];        // toàn bộ mẫu (dùng cho dropdown)
scwin.eventTpl = {};         // NAMECARD / NAMEPLACE -> mẫu đang áp dụng cho sự kiện
scwin.queue = { page: 0, totalPages: 0, items: [] };
scwin.hist = { page: 0, totalPages: 0, items: [] };
scwin.job = null;
scwin.jobBlob = null;
scwin.pdfUrls = {};
scwin.open = { job: false, pv: false, ask: false, confirm: false };
scwin.timers = {};

/* =====================================================================
 * VÒNG ĐỜI
 * ===================================================================== */
scwin.onpageload = function () {
    if (!scwin.getToken()) { scwin.goLogin(); return; }
    var printer = "";
    try { printer = window.localStorage.getItem(scwin.PRINTER_KEY) || ""; } catch (e) { }
    dma_print.setJSON({ eventId: scwin.getQueryParam("eventId"), templateId: "", copies: "1", printerName: printer, paperSize: "",
        onlyNotPrinted: "", allType: "", allChecked: "", keyword: "", qStatus: "", qType: "", hType: "", tType: "", tKeyword: "" });

    // Nhận danh sách khách được chọn từ màn Khách mời
    var handoff = null;
    try { handoff = scwin.parseJSON(window.sessionStorage.getItem(scwin.HANDOFF_KEY)); window.sessionStorage.removeItem(scwin.HANDOFF_KEY); } catch (e) { }
    if (handoff && handoff.guests && handoff.guests.length) {
        dma_print.set("eventId", String(handoff.eventId));
        scwin.state.printType = handoff.printType || "NAMECARD";
        handoff.guests.forEach(function (g) { scwin.addPicked(g.guestId, g.fullName); });
        setTimeout(function () { scwin.toast("Đã nhận " + handoff.guests.length + " khách từ danh sách khách mời.", "info"); }, 400);
    }
    scwin.keyHandler = function (e) { scwin.onGlobalKeydown(e); };
    document.addEventListener("keydown", scwin.keyHandler);
    scwin.initImportInput();
    scwin.applyPermissions();
    scwin.setPrintType(scwin.state.printType, true);
    scwin.setScope("selected");
    scwin.setTab(scwin.getQueryParam("tab") || "new");
    scwin.loadLookups();
    scwin.loadTemplates();
};
scwin.onpageunload = function () {
    document.removeEventListener("keydown", scwin.keyHandler);
    for (var k in scwin.pdfUrls) if (scwin.pdfUrls.hasOwnProperty(k)) try { URL.revokeObjectURL(scwin.pdfUrls[k]); } catch (e) { }
};

scwin.applyPermissions = function () {
    var manage = scwin.can("TEMPLATE_MANAGE");
    scwin.show(btn_tNew, manage);
    scwin.show(btn_tImport, manage);
    scwin.show(grp_evTplActions, manage);
};

scwin.loadLookups = function () {
    scwin.callApi("sbm_lookups", { url: scwin.GUEST_API + "/lookups" }).then(function (d) {
        scwin.lookups.events = (d && d.events) || [];
        scwin.lookups.guestTypes = (d && d.guestTypes) || [];
        dlt_events.setJSON(scwin.lookups.events.map(function (e) { return { eventId: String(e.eventId), label: scwin.eventLabel(e) }; }));
        dlt_types.setJSON(scwin.lookups.guestTypes.map(function (t) { return { code: t.code, name: scwin.typeName(t.code) }; }));
        sbx_event.setValue(dma_print.get("eventId") || "");
        scwin.onEventChanged(true);
    }).catch(function (err) { scwin.toast("Không tải được danh sách sự kiện: " + err.message, "error"); });
};

/* ---------- Sự kiện ---------- */
scwin.sbx_event_onchange = function () {
    var id = sbx_event.getValue() || "";
    if (id !== dma_print.get("eventId")) { scwin.picked = {}; scwin.pickedOrder = []; }
    dma_print.set("eventId", id);
    scwin.onEventChanged(false);
};
scwin.onEventChanged = function () {
    var id = dma_print.get("eventId");
    scwin.show(grp_noEvent, !id);
    scwin.show(grp_newBody, !!id);
    scwin.loadEventTemplates();
    scwin.loadPick(true);
    scwin.renderPicked();
    if (scwin.state.tab === "queue") scwin.loadQueue(true);
    if (scwin.state.tab === "history") scwin.loadHistory(true);
};

/* =====================================================================
 * TAB
 * ===================================================================== */
scwin.TABS = { "new": ["btn_tabNew", "grp_tNew"], queue: ["btn_tabQueue", "grp_tQueue"], history: ["btn_tabHistory", "grp_tHistory"], templates: ["btn_tabTemplates", "grp_tTemplates"] };
scwin.setTab = function (tab) {
    if (!scwin.TABS[tab]) tab = "new";
    scwin.state.tab = tab;
    for (var k in scwin.TABS) {
        if (!scwin.TABS.hasOwnProperty(k)) continue;
        scwin.toggleClass(scwin.comp(scwin.TABS[k][0]), "is-selected", k === tab);
        scwin.show(scwin.comp(scwin.TABS[k][1]), k === tab);
    }
    if (tab === "queue") scwin.loadQueue(true);
    if (tab === "history") scwin.loadHistory(true);
    if (tab === "templates") scwin.renderTemplateGrid();
};
scwin.btn_tabNew_onclick = function () { scwin.setTab("new"); };
scwin.btn_tabQueue_onclick = function () { scwin.setTab("queue"); };
scwin.btn_tabHistory_onclick = function () { scwin.setTab("history"); };
scwin.btn_tabTemplates_onclick = function () { scwin.setTab("templates"); };

/* =====================================================================
 * MẪU IN
 * ===================================================================== */
scwin.loadTemplates = function () {
    return scwin.callApi("sbm_templates", { url: scwin.TPL_API + "?" + scwin.buildQuery({ page: 0, size: 50 }) }).then(function (page) {
        scwin.templates = (page && page.content) || [];
        scwin.fillTemplateSelect();
        scwin.renderTemplateGrid();
    }).catch(function (err) { scwin.toast("Không tải được mẫu in: " + err.message, "warning"); });
};
scwin.tplLabel = function (t) {
    var w = t.pageWidthMm ? Math.round(t.pageWidthMm) + "×" + Math.round(t.pageHeightMm) + " mm" : (scwin.PAPER_VN[t.paperSize] || t.paperSize);
    return t.templateName + " (" + w + (t.systemDefault ? ", mặc định hệ thống" : "") + ")";
};
scwin.findTpl = function (id) { for (var i = 0; i < scwin.templates.length; i++) if (String(scwin.templates[i].templateId) === String(id)) return scwin.templates[i]; return null; };
scwin.fillTemplateSelect = function () {
    var type = scwin.state.printType;
    dlt_tplOptions.setJSON(scwin.templates.filter(function (t) { return t.templateType === type; })
        .map(function (t) { return { templateId: String(t.templateId), label: scwin.tplLabel(t) }; }));
    var cur = dma_print.get("templateId");
    if (cur && !scwin.findTpl(cur)) dma_print.set("templateId", "");
    sbx_template.setValue(dma_print.get("templateId") || "");
    scwin.updateTplHint();
};
scwin.loadEventTemplates = function () {
    var id = dma_print.get("eventId");
    scwin.eventTpl = {};
    scwin.renderEventTpl();
    if (!id) return;
    scwin.callApi("sbm_eventTemplates", { url: scwin.EVENT_API + "/" + id + "/print-templates" }).then(function (list) {
        if (dma_print.get("eventId") !== id) return;
        (list || []).forEach(function (x) { scwin.eventTpl[x.templateType] = x; });
        scwin.renderEventTpl();
        scwin.updateTplHint();
    }).catch(function () { });
};
scwin.updateTplHint = function () {
    var chosen = scwin.findTpl(dma_print.get("templateId"));
    var ev = scwin.eventTpl[scwin.state.printType];
    var t = chosen || (ev && ev.templateId ? scwin.findTpl(ev.templateId) || { templateName: ev.templateName } : null);
    tbx_tplHint.setValue(chosen ? "Dùng mẫu đã chọn." : ev ? "Đang dùng " + (scwin.SOURCE_VN[ev.source] || "") + (ev.templateName ? ": " + ev.templateName : "") + "." : "");
    tbx_paperInfo.setValue(t && t.paperSize ? "Khổ giấy của mẫu: " + (scwin.PAPER_VN[t.paperSize] || t.paperSize) + (t.pageWidthMm ? " (" + Math.round(t.pageWidthMm) + "×" + Math.round(t.pageHeightMm) + " mm)" : "") : "");
    scwin.updateSummary();
};
scwin.sbx_template_onchange = function () { dma_print.set("templateId", sbx_template.getValue() || ""); scwin.updateTplHint(); };

/* =====================================================================
 * TAB TẠO LỆNH IN: CẤU HÌNH
 * ===================================================================== */
scwin.setPrintType = function (t, silent) {
    scwin.state.printType = t;
    scwin.toggleClass(btn_ptCard, "is-selected", t === "NAMECARD");
    scwin.toggleClass(btn_ptPlace, "is-selected", t === "NAMEPLACE");
    dma_print.set("templateId", "");
    scwin.fillTemplateSelect();
    if (!silent) scwin.loadPick(true);
    chk_onlyNew.setValue("");
    tbx_onlyNewHint.setValue(t === "NAMECARD" ? "Bỏ qua khách đã có thẻ tên (in bổ sung)." : "Bỏ qua khách đã có danh bạ để bàn.");
};
scwin.btn_ptCard_onclick = function () { scwin.setPrintType("NAMECARD"); };
scwin.btn_ptPlace_onclick = function () { scwin.setPrintType("NAMEPLACE"); };

scwin.setScope = function (s) {
    scwin.state.scope = s;
    scwin.toggleClass(btn_scSelected, "is-selected", s === "selected");
    scwin.toggleClass(btn_scAll, "is-selected", s === "all");
    scwin.show(grp_pickBox, s === "selected");
    scwin.show(grp_allBox, s === "all");
    scwin.updateSummary();
};
scwin.btn_scSelected_onclick = function () { scwin.setScope("selected"); };
scwin.btn_scAll_onclick = function () { scwin.setScope("all"); };
scwin.opt_onchange = function () { scwin.updateSummary(); };
scwin.ibx_printer_onblur = function () { try { window.localStorage.setItem(scwin.PRINTER_KEY, scwin.trim(ibx_printer.getValue())); } catch (e) { } };

scwin.updateSummary = function () {
    if (typeof tbx_summary === "undefined") return;
    var copies = parseInt(ibx_copies.getValue(), 10) || 1;
    var who = scwin.state.scope === "all" ? "toàn bộ khách của sự kiện" + (sbx_allType.getValue() || sbx_allChecked.getValue() ? " (đã lọc)" : "")
        : scwin.fmtNumber(scwin.pickedOrder.length) + " khách đã chọn";
    tbx_summary.setValue("In " + scwin.TYPE_VN[scwin.state.printType].toLowerCase() + " cho " + who + ", " + copies + " bản mỗi khách"
        + (String(chk_onlyNew.getValue() || "") ? ", bỏ qua khách đã in" : "") + ".");
};

/* =====================================================================
 * TAB TẠO LỆNH IN: CHỌN KHÁCH
 * ===================================================================== */
scwin.addPicked = function (id, name) {
    id = String(id);
    if (!scwin.picked[id]) scwin.pickedOrder.push(id);
    scwin.picked[id] = { guestId: id, fullName: name };
};
scwin.removePicked = function (id) {
    id = String(id);
    delete scwin.picked[id];
    var i = scwin.pickedOrder.indexOf(id);
    if (i >= 0) scwin.pickedOrder.splice(i, 1);
};
scwin.loadPick = function (reset) {
    var eventId = dma_print.get("eventId");
    if (!eventId) return;
    var st = scwin.pick;
    if (reset) { st.page = 0; st.items = []; }
    var seq = ++st.seq;
    grp_pickWrap.addClass("is-loading");
    var q = { eventId: eventId, keyword: scwin.trim(ibx_pickSearch.getValue()), page: st.page, size: 50, sort: "tableNumber,asc" };
    scwin.callApi("sbm_guestPick", { url: scwin.GUEST_API + "?" + scwin.buildQuery(q) }).then(function (page) {
        if (seq !== st.seq) return;
        st.items = st.items.concat((page && page.content) || []);
        st.totalPages = (page && page.totalPages) || 0;
        st.totalElements = (page && page.totalElements) || 0;
        st.page += 1;
        scwin.renderPick();
    }).catch(function (err) { scwin.toast(err.message, "error"); })
      .then(function () { if (seq === st.seq) grp_pickWrap.removeClass("is-loading"); });
};
scwin.renderPick = function () {
    var st = scwin.pick, printed = scwin.state.printType === "NAMECARD" ? "badgePrinted" : "nameplacePrinted";
    scwin.pickLock = true;
    dlt_pick.setJSON(st.items.map(function (g) {
        return { chk: scwin.picked[String(g.guestId)] ? "1" : "0", guestId: String(g.guestId), fullName: g.fullName, company: g.company || "",
                 guestTypeCode: g.guestTypeCode, tableNumber: g.tableNumber || "", printed: g[printed] ? "1" : "0" };
    }));
    scwin.pickLock = false;
    for (var i = 0; i < st.items.length; i++) {
        try { grd_pick.setCellClass(i, "printed", st.items[i][printed] ? "pr-printed--yes" : "pr-printed--no"); } catch (e) { }
    }
    scwin.fitGrid(grd_pick, st.items.length, 44, 9);
    scwin.show(grp_pickEmpty, !st.items.length);
    scwin.show(btn_pickMore, st.page < st.totalPages);
    tbx_pickInfo.setValue(st.totalElements ? "Hiển thị " + st.items.length + "/" + scwin.fmtNumber(st.totalElements) + " khách" : "");
    scwin.renderPicked();
};
scwin.syncPick = function () {
    if (scwin.pickLock) return;
    for (var i = 0; i < dlt_pick.getRowCount(); i++) {
        var r = dlt_pick.getRowJSON(i);
        if (r.chk === "1" || r.chk === 1 || r.chk === true) scwin.addPicked(r.guestId, r.fullName);
        else if (scwin.picked[r.guestId]) scwin.removePicked(r.guestId);
    }
    scwin.renderPicked();
};
scwin.dlt_pick_oncelldatachange = function (info) {
    if (info && info.colID && info.colID !== "chk") return;
    clearTimeout(scwin.timers.pick); scwin.timers.pick = setTimeout(scwin.syncPick, 60);
};
scwin.grd_pick_oncellclick = function (row, col, colId) {
    if (colId === "chk") { clearTimeout(scwin.timers.pick); scwin.timers.pick = setTimeout(scwin.syncPick, 60); return; }
    var r = dlt_pick.getRowJSON(row);
    if (!r) return;
    dlt_pick.setCellData(row, "chk", r.chk === "1" ? "0" : "1");
    clearTimeout(scwin.timers.pick); scwin.timers.pick = setTimeout(scwin.syncPick, 60);
};
scwin.grd_pick_onheaderclick = function () { clearTimeout(scwin.timers.pick); scwin.timers.pick = setTimeout(scwin.syncPick, 80); };
scwin.renderPicked = function () {
    var n = scwin.pickedOrder.length;
    tbx_pickedCount.setValue(n ? "Đã chọn " + scwin.fmtNumber(n) + " khách" : "Chưa chọn khách nào");
    var names = scwin.pickedOrder.slice(0, 6).map(function (id) { return scwin.picked[id].fullName; });
    tbx_pickedNames.setValue(n ? names.join(", ") + (n > 6 ? " và " + (n - 6) + " khách khác" : "") : "Tích chọn khách trong bảng bên dưới.");
    scwin.show(btn_pickClear, n > 0);
    scwin.updateSummary();
};
scwin.ibx_pickSearch_onkeyup = function () { clearTimeout(scwin.timers.ps); scwin.timers.ps = setTimeout(function () { scwin.loadPick(true); }, 350); };
scwin.btn_pickMore_onclick = function () { scwin.loadPick(false); };
scwin.btn_pickPage_onclick = function () {
    for (var i = 0; i < dlt_pick.getRowCount(); i++) dlt_pick.setCellData(i, "chk", "1");
    scwin.syncPick();
};
scwin.btn_pickUnprinted_onclick = function () {
    for (var i = 0; i < dlt_pick.getRowCount(); i++) if (dlt_pick.getCellData(i, "printed") !== "1") dlt_pick.setCellData(i, "chk", "1");
    scwin.syncPick();
};
scwin.btn_pickClear_onclick = function () {
    scwin.picked = {}; scwin.pickedOrder = [];
    for (var i = 0; i < dlt_pick.getRowCount(); i++) dlt_pick.setCellData(i, "chk", "0");
    scwin.renderPicked();
};
scwin.gfType = function (v) { return scwin.typeName(v); };
scwin.gfPrinted = function (v) { return v === "1" ? "Đã in" : "Chưa in"; };
scwin.gfDash = function (v) { return scwin.dash(v); };

/* =====================================================================
 * TAB TẠO LỆNH IN: XEM TRƯỚC & TẠO LỆNH
 * ===================================================================== */
scwin.buildRequest = function () {
    var eventId = dma_print.get("eventId");
    if (!eventId) { scwin.toast("Chọn sự kiện trước.", "warning"); return null; }
    var copies = parseInt(ibx_copies.getValue(), 10);
    if (!copies || copies < 1 || copies > 10) { scwin.toast("Số bản mỗi khách từ 1 đến 10.", "warning"); try { ibx_copies.focus(); } catch (e) { } return null; }
    var r = {
        eventId: Number(eventId), printType: scwin.state.printType,
        templateId: sbx_template.getValue() ? Number(sbx_template.getValue()) : null,
        copies: copies, printerName: scwin.trim(ibx_printer.getValue()) || null,
        paperSize: sbx_paper.getValue() || null,
        onlyNotPrinted: !!String(chk_onlyNew.getValue() || "")
    };
    if (scwin.state.scope === "all") {
        r.allGuests = true;
        var f = {};
        if (sbx_allType.getValue()) f.guestTypeCodes = [sbx_allType.getValue()];
        if (sbx_allChecked.getValue()) f.checkedIn = sbx_allChecked.getValue() === "true";
        r.filter = Object.keys(f).length ? f : null;
    } else {
        if (!scwin.pickedOrder.length) { scwin.toast("Chọn ít nhất một khách để in.", "warning"); return null; }
        if (scwin.pickedOrder.length > 1000) { scwin.toast("Mỗi lệnh in tối đa 1.000 khách.", "warning"); return null; }
        r.guestIds = scwin.pickedOrder.map(Number);
    }
    return r;
};

/** Hiển thị PDF trong một khung (iframe được tạo bằng script bên trong group). */
scwin.showPdf = function (hostComp, key, blob) {
    var host = scwin.domOf(hostComp);
    if (!host) return;
    if (scwin.pdfUrls[key]) try { URL.revokeObjectURL(scwin.pdfUrls[key]); } catch (e) { }
    scwin.pdfUrls[key] = URL.createObjectURL(blob);
    var f = host.querySelector("iframe");
    if (!f) { f = document.createElement("iframe"); f.className = "pr-pdf"; f.title = "Bản xem trước PDF"; host.appendChild(f); }
    f.src = scwin.pdfUrls[key] + "#toolbar=1&navpanes=0&view=FitH";
    hostComp.addClass("has-pdf");
};

scwin.btn_preview_onclick = function () {
    var r = scwin.buildRequest();
    if (!r) return;
    btn_preview.addClass("is-busy");
    grp_previewBox.addClass("is-loading");
    scwin.xhr("POST", scwin.PRINT_API + "/preview", { body: r, responseType: "blob" }).then(function (res) {
        scwin.showPdf(grp_previewBox, "preview", res.blob);
        tbx_previewHint.setValue("Bản xem trước hiển thị tối đa 20 khách đầu. Bản xem trước không đánh dấu khách đã in.");
    }).catch(scwin.handlePrintError)
      .then(function () { btn_preview.removeClass("is-busy"); grp_previewBox.removeClass("is-loading"); });
};

scwin.handlePrintError = function (err) {
    var msg = err.message;
    if (err.code === "NO_GUESTS") msg = "Không còn khách nào để in sau khi lọc" + (String(chk_onlyNew.getValue() || "") ? " (có thể tất cả đã được in)." : ".");
    scwin.toast(msg, "error");
};

scwin.btn_createJob_onclick = function () {
    var r = scwin.buildRequest();
    if (!r) return;
    btn_createJob.addClass("is-busy");
    scwin.callApi("sbm_jobCreate", { url: scwin.PRINT_API + "/jobs", body: r }).then(function (job) {
        scwin.toast("Đã tạo lệnh in #" + job.jobId + ": " + job.totalItems + " khách, " + job.totalPages + " trang.", "success");
        scwin.openJob(job);
    }).catch(scwin.handlePrintError)
      .then(function () { btn_createJob.removeClass("is-busy"); });
};

/* =====================================================================
 * LỆNH IN: GỬI MÁY IN, ĐÁNH DẤU ĐÃ IN
 * ===================================================================== */
scwin.openJob = function (job) {
    scwin.job = job;
    scwin.jobBlob = null;
    scwin.renderJob();
    scwin.open.job = true;
    grp_jobMask.addClass("is-open");
    grp_jobPdf.removeClass("has-pdf");
    var host = scwin.domOf(grp_jobPdf), f = host && host.querySelector("iframe");
    if (f) f.src = "about:blank";
    if (job.status === "CANCELLED") { tbx_jPdfHint.setValue("Lệnh in đã hủy, không còn file PDF."); return; }
    tbx_jPdfHint.setValue("Đang tải file PDF…");
    grp_jobPdf.addClass("is-loading");
    scwin.xhr("GET", scwin.PRINT_API + "/jobs/" + job.jobId + "/pdf?download=false", { responseType: "blob" }).then(function (r) {
        if (!scwin.job || scwin.job.jobId !== job.jobId) return;
        scwin.jobBlob = r.blob;
        scwin.showPdf(grp_jobPdf, "job", r.blob);
        tbx_jPdfHint.setValue("");
    }).catch(function (err) { tbx_jPdfHint.setValue("Không tải được PDF: " + err.message); })
      .then(function () { grp_jobPdf.removeClass("is-loading"); });
};
scwin.renderJob = function () {
    var j = scwin.job;
    tbx_jTitle.setValue("Lệnh in #" + j.jobId + ": " + scwin.TYPE_VN[j.printType]);
    tbx_jMeta.setValue([j.eventCode + " " + (j.eventName || ""), "mẫu " + (j.templateName || "—"),
        scwin.fmtNumber(j.totalItems) + " khách, " + scwin.fmtNumber(j.totalPages) + " trang (" + j.copies + " bản/khách)",
        j.printerName ? "máy in " + j.printerName : "", j.paperSize ? "khổ " + (scwin.PAPER_VN[j.paperSize] || j.paperSize) : ""
    ].filter(function (x) { return !!x; }).join("; "));
    tbx_jStatus.setValue(scwin.JOB_VN[j.status] || j.status);
    ["QUEUED", "PRINTING", "COMPLETED", "FAILED", "CANCELLED"].forEach(function (s) { scwin.toggleClass(tbx_jStatus, "pr-job--" + s, s === j.status); });
    tbx_jError.setValue(j.errorMessage ? "Lỗi đã báo: " + j.errorMessage : "");
    scwin.show(tbx_jError, !!j.errorMessage);
    var s = j.status;
    scwin.show(btn_jPrint, s === "QUEUED" || s === "FAILED" || s === "PRINTING");
    btn_jPrint.setValue(s === "PRINTING" ? "Mở lại hộp thoại in" : "Gửi tới máy in");
    scwin.show(btn_jDone, s === "QUEUED" || s === "PRINTING" || s === "FAILED");
    scwin.show(btn_jFail, s === "QUEUED" || s === "PRINTING");
    scwin.show(btn_jCancel, s === "QUEUED" || s === "PRINTING" || s === "FAILED");
    scwin.show(btn_jDownload, s !== "CANCELLED");
    scwin.show(grp_jReason, false);
    tbx_jGuide.setValue(s === "COMPLETED" ? "Đã in xong lúc " + scwin.fmtDateTime(j.completedAt) + ". Khách trong lệnh đã được đánh dấu đã in."
        : s === "CANCELLED" ? "Lệnh in đã bị hủy."
        : "Bước 1: Gửi tới máy in và chọn đúng máy in, khổ giấy trong hộp thoại. Bước 2: Kiểm tra bản in. Bước 3: Bấm Đã in xong để đánh dấu khách đã in.");
};
scwin.jobAction = function (action, body, btn) {
    var j = scwin.job;
    if (btn) btn.addClass("is-busy");
    return scwin.callApi("sbm_jobAction", { url: scwin.PRINT_API + "/jobs/" + j.jobId + "/" + action, body: body || {} }).then(function (job) {
        scwin.job = job;
        scwin.renderJob();
        if (scwin.state.tab === "queue") scwin.loadQueue(true);
        return job;
    }).catch(function (err) { scwin.toast(err.message, "error"); throw err; })
      .then(function (r) { if (btn) btn.removeClass("is-busy"); return r; }, function () { if (btn) btn.removeClass("is-busy"); });
};
scwin.btn_jPrint_onclick = function () {
    if (!scwin.jobBlob) { scwin.toast("File PDF chưa tải xong.", "warning"); return; }
    var start = scwin.job.status === "PRINTING" ? Promise.resolve() : scwin.jobAction("start", null, btn_jPrint);
    start.then(function () { scwin.printBlob(scwin.jobBlob); });
};
scwin.btn_jDone_onclick = function () {
    scwin.jobAction("complete", null, btn_jDone).then(function (job) {
        if (!job) return;
        scwin.toast("Đã đánh dấu " + scwin.fmtNumber(job.totalItems) + " khách đã in.", "success");
        scwin.loadPick(true);
    });
};
scwin.btn_jFail_onclick = function () { scwin.show(grp_jReason, true); setTimeout(function () { try { ibx_jReason.focus(); } catch (e) { } }, 50); };
scwin.btn_jReasonOk_onclick = function () {
    scwin.jobAction("fail", { errorMessage: scwin.trim(ibx_jReason.getValue()) || null }, btn_jReasonOk).then(function (job) {
        if (job) scwin.toast("Đã ghi nhận lỗi in. Có thể gửi lại tới máy in khi sẵn sàng.", "info");
    });
};
scwin.btn_jCancel_onclick = function () {
    scwin.openConfirm({ title: "Hủy lệnh in #" + scwin.job.jobId + "?", message: "Khách trong lệnh sẽ không được đánh dấu đã in.", okText: "Hủy lệnh", danger: true,
        onOk: function () { scwin.jobAction("cancel", null, btn_jCancel).then(function (j) { if (j) scwin.toast("Đã hủy lệnh in.", "info"); }); } });
};
scwin.btn_jDownload_onclick = function () {
    scwin.downloadFile(scwin.PRINT_API + "/jobs/" + scwin.job.jobId + "/pdf?download=true", "LenhIn-" + scwin.job.jobId + ".pdf", btn_jDownload);
};
scwin.closeJob = function () { scwin.open.job = false; grp_jobMask.removeClass("is-open"); };
scwin.btn_jClose_onclick = scwin.closeJob;

/* =====================================================================
 * TAB HÀNG ĐỢI IN
 * ===================================================================== */
scwin.loadQueue = function (reset) {
    var st = scwin.queue;
    if (reset) { st.page = 0; st.items = []; }
    grp_qWrap.addClass("is-loading");
    var q = { eventId: dma_print.get("eventId"), status: sbx_qStatus.getValue(), printType: sbx_qType.getValue(), page: st.page, size: 20 };
    scwin.callApi("sbm_jobs", { url: scwin.PRINT_API + "/jobs?" + scwin.buildQuery(q) }).then(function (page) {
        st.items = st.items.concat((page && page.content) || []);
        st.totalPages = (page && page.totalPages) || 0;
        st.page += 1;
        dlt_jobs.setJSON(st.items);
        for (var i = 0; i < st.items.length; i++) { try { grd_jobs.setCellClass(i, "status", "pr-job pr-job--" + st.items[i].status); } catch (e) { } }
        scwin.fitGrid(grd_jobs, st.items.length, 48);
        scwin.show(grp_qEmpty, !st.items.length);
        scwin.show(btn_qMore, st.page < st.totalPages);
        var waiting = st.items.filter(function (j) { return j.status === "QUEUED" || j.status === "PRINTING" || j.status === "FAILED"; }).length;
        btn_tabQueue.setValue("Hàng đợi in" + (waiting ? " (" + waiting + ")" : ""));
    }).catch(function (err) { scwin.toast(err.message, "error"); })
      .then(function () { grp_qWrap.removeClass("is-loading"); });
};
scwin.sbx_qStatus_onchange = function () { scwin.loadQueue(true); };
scwin.sbx_qType_onchange = function () { scwin.loadQueue(true); };
scwin.btn_qRefresh_onclick = function () { scwin.loadQueue(true); };
scwin.btn_qMore_onclick = function () { scwin.loadQueue(false); };
scwin.grd_jobs_oncellclick = function (row) { var j = scwin.queue.items[row]; if (j) scwin.openJob(j); };
scwin.gfJobType = function (v) { return scwin.TYPE_VN[v] || v; };
scwin.gfJobStatus = function (v) { return "● " + (scwin.JOB_VN[v] || v); };
scwin.gfJobSize = function (v, f, i) { var j = scwin.queue.items[i] || {}; return scwin.fmtNumber(j.totalItems) + " khách, " + scwin.fmtNumber(j.totalPages) + " trang"; };
scwin.gfDateTime = function (v) { return v ? scwin.fmtDateTime(v) : "—"; };
scwin.gfJobEvent = function (v, f, i) { var j = scwin.queue.items[i] || {}; return j.eventCode || "—"; };

/* =====================================================================
 * TAB LỊCH SỬ IN
 * ===================================================================== */
scwin.loadHistory = function (reset) {
    var st = scwin.hist, eventId = dma_print.get("eventId");
    if (!eventId) { dlt_logs.setJSON([]); scwin.fitGrid(grd_logs, 0); tbx_hEmpty.setValue("Chọn sự kiện để xem lịch sử in."); scwin.show(grp_hEmpty, true); scwin.show(btn_hMore, false); return; }
    if (reset) { st.page = 0; st.items = []; }
    grp_hWrap.addClass("is-loading");
    var q = { eventId: eventId, printType: sbx_hType.getValue(), page: st.page, size: 30 };
    scwin.callApi("sbm_logs", { url: scwin.PRINT_API + "/logs?" + scwin.buildQuery(q) }).then(function (page) {
        st.items = st.items.concat((page && page.content) || []);
        st.totalPages = (page && page.totalPages) || 0;
        st.page += 1;
        dlt_logs.setJSON(st.items);
        scwin.fitGrid(grd_logs, st.items.length, 46);
        tbx_hEmpty.setValue("Sự kiện chưa in thẻ tên hoặc danh bạ nào.");
        scwin.show(grp_hEmpty, !st.items.length);
        scwin.show(btn_hMore, st.page < st.totalPages);
    }).catch(function (err) { scwin.toast(err.message, "error"); })
      .then(function () { grp_hWrap.removeClass("is-loading"); });
};
scwin.sbx_hType_onchange = function () { scwin.loadHistory(true); };
scwin.btn_hMore_onclick = function () { scwin.loadHistory(false); };
scwin.gfLogType = function (v, f, i) { var l = scwin.hist.items[i] || {}; return (scwin.TYPE_VN[v] || v) + (l.reprint ? " (in lại)" : ""); };

/* =====================================================================
 * TAB MẪU IN
 * ===================================================================== */
scwin.renderEventTpl = function () {
    var id = dma_print.get("eventId");
    scwin.show(grp_evTpl, !!id);
    if (!id) return;
    ["NAMECARD", "NAMEPLACE"].forEach(function (type) {
        var x = scwin.eventTpl[type], tb = type === "NAMECARD" ? tbx_evCard : tbx_evPlace, btn = type === "NAMECARD" ? btn_evCardReset : btn_evPlaceReset;
        tb.setValue(x ? (x.templateName || "Chưa có mẫu") + " (" + (scwin.SOURCE_VN[x.source] || x.source) + ")" : "Đang tải…");
        scwin.show(btn, !!(x && x.source === "EVENT") && scwin.can("TEMPLATE_MANAGE"));
    });
};
scwin.renderTemplateGrid = function () {
    var type = sbx_tType.getValue(), kw = scwin.trim(ibx_tKeyword.getValue()).toLowerCase();
    var list = scwin.templates.filter(function (t) {
        return (!type || t.templateType === type) && (!kw || String(t.templateName).toLowerCase().indexOf(kw) >= 0);
    });
    scwin.tplRows = list;
    var manage = scwin.can("TEMPLATE_MANAGE");
    dlt_tpls.setJSON(list.map(function (t) {
        var ev = scwin.eventTpl[t.templateType];
        return { templateId: String(t.templateId), templateName: t.templateName, templateType: t.templateType, paperSize: t.paperSize,
                 sizeText: t.pageWidthMm ? Math.round(t.pageWidthMm) + "×" + Math.round(t.pageHeightMm) + " mm" : "",
                 flags: (t.systemDefault ? "Mặc định hệ thống" : "") + (ev && String(ev.templateId) === String(t.templateId) && ev.source === "EVENT" ? (t.systemDefault ? ", " : "") + "Đang dùng cho sự kiện" : ""),
                 updatedAt: t.updatedAt, actPreview: "", actEdit: manage ? "x" : "", actUse: manage ? "x" : "", actClone: manage ? "x" : "", actExport: "x", actDelete: manage && !t.systemDefault ? "x" : "" };
    }));
    scwin.fitGrid(grd_tpls, list.length, 50);
    scwin.show(grp_tEmpty, !list.length);
};
scwin.sbx_tType_onchange = function () { scwin.renderTemplateGrid(); };
scwin.ibx_tKeyword_onkeyup = function () { clearTimeout(scwin.timers.tk); scwin.timers.tk = setTimeout(scwin.renderTemplateGrid, 250); };
scwin.gfTplType = function (v) { return scwin.TYPE_VN[v] || v; };
scwin.gfTplPaper = function (v, f, i) { var r = dlt_tpls.getRowJSON(i) || {}; return (scwin.PAPER_VN[v] || v) + (r.sizeText ? ", " + r.sizeText : ""); };
scwin.gfAct = function (label) { return function (v) { return v ? label : ""; }; };
scwin.gfActPreview = function () { return "Xem"; };
scwin.gfActEdit = scwin.gfAct("Sửa");
scwin.gfActUse = scwin.gfAct("Dùng cho sự kiện");
scwin.gfActClone = scwin.gfAct("Nhân bản");
scwin.gfActExport = scwin.gfAct("Xuất");
scwin.gfActDelete = scwin.gfAct("Xóa");

scwin.grd_tpls_oncellclick = function (row, col, colId) {
    var t = scwin.tplRows[row];
    if (!t) return;
    var manage = scwin.can("TEMPLATE_MANAGE");
    if (colId === "actPreview") scwin.previewTemplate(t);
    else if (colId === "actEdit" && manage) scwin.goDesigner(t.templateId);
    else if (colId === "actUse" && manage) scwin.useForEvent(t);
    else if (colId === "actClone" && manage) scwin.cloneTemplate(t);
    else if (colId === "actExport") scwin.downloadFile(scwin.TPL_API + "/" + t.templateId + "/export", "MauIn-" + t.templateType + "-" + t.templateId + ".json");
    else if (colId === "actDelete" && manage && !t.systemDefault) scwin.deleteTemplate(t);
    else scwin.previewTemplate(t);
};
scwin.goDesigner = function (id) { window.location.href = scwin.pageUrl(scwin.DESIGNER_PAGE, { templateId: id || "", eventId: dma_print.get("eventId") }); };
scwin.btn_tNew_onclick = function () { scwin.goDesigner(""); };

scwin.previewTemplate = function (t) {
    tbx_pvTitle.setValue("Xem trước: " + t.templateName);
    tbx_pvHint.setValue(dma_print.get("eventId") ? "In thử với khách đầu tiên của sự kiện đang chọn." : "In thử với dữ liệu mẫu.");
    scwin.open.pv = true;
    grp_pvMask.addClass("is-open");
    grp_pvFrame.addClass("is-loading");
    scwin.xhr("GET", scwin.TPL_API + "/" + t.templateId + "/preview?" + scwin.buildQuery({ eventId: dma_print.get("eventId") }), { responseType: "blob" })
        .then(function (r) { scwin.showPdf(grp_pvFrame, "tpl", r.blob); })
        .catch(function (err) { tbx_pvHint.setValue("Không tạo được bản xem trước: " + err.message); })
        .then(function () { grp_pvFrame.removeClass("is-loading"); });
};
scwin.closePv = function () { scwin.open.pv = false; grp_pvMask.removeClass("is-open"); };
scwin.btn_pvClose_onclick = scwin.closePv;

scwin.useForEvent = function (t) {
    var id = dma_print.get("eventId");
    if (!id) { scwin.toast("Chọn sự kiện ở đầu trang trước.", "warning"); return; }
    scwin.callApi("sbm_setEventTpl", { url: scwin.EVENT_API + "/" + id + "/print-templates/" + t.templateType, body: { templateId: Number(t.templateId) } }).then(function () {
        scwin.toast("Sự kiện sẽ dùng mẫu " + t.templateName + " cho " + scwin.TYPE_VN[t.templateType].toLowerCase() + ".", "success");
        scwin.loadEventTemplates();
        setTimeout(scwin.renderTemplateGrid, 300);
    }).catch(function (err) { scwin.toast(err.message, "error"); });
};
scwin.resetEventTpl = function (type) {
    var id = dma_print.get("eventId");
    scwin.callApi("sbm_unsetEventTpl", { url: scwin.EVENT_API + "/" + id + "/print-templates/" + type }).then(function () {
        scwin.toast("Đã quay về mẫu mặc định hệ thống.", "success");
        scwin.loadEventTemplates();
        setTimeout(scwin.renderTemplateGrid, 300);
    }).catch(function (err) { scwin.toast(err.message, "error"); });
};
scwin.btn_evCardReset_onclick = function () { scwin.resetEventTpl("NAMECARD"); };
scwin.btn_evPlaceReset_onclick = function () { scwin.resetEventTpl("NAMEPLACE"); };

scwin.cloneTemplate = function (t) {
    scwin.openAsk({ title: "Nhân bản mẫu", label: "Tên mẫu mới", value: t.templateName + " (bản sao)", okText: "Nhân bản", onOk: function (name) {
        return scwin.callApi("sbm_tplClone", { url: scwin.TPL_API + "/" + t.templateId + "/clone", body: { templateName: name || null } }).then(function (nt) {
            scwin.toast("Đã tạo " + nt.templateName + ".", "success");
            return scwin.loadTemplates();
        });
    } });
};
scwin.deleteTemplate = function (t) {
    scwin.openConfirm({ title: "Xóa mẫu " + t.templateName + "?", message: "Mẫu sẽ bị ẩn khỏi danh sách. Lịch sử in dùng mẫu này vẫn được giữ.", okText: "Xóa mẫu", danger: true, onOk: function () {
        scwin.callApi("sbm_tplDelete", { url: scwin.TPL_API + "/" + t.templateId + "?confirm=true" }).then(function () {
            scwin.toast("Đã xóa mẫu.", "success"); scwin.loadTemplates();
        }).catch(function (err) {
            scwin.toast(err.code === "TEMPLATE_IN_USE" ? "Mẫu đang được sự kiện sử dụng. Đổi mẫu của sự kiện trước rồi xóa." : err.message, "error");
        });
    } });
};

/* ---------- Import mẫu (.json) ---------- */
scwin.initImportInput = function () {
    var inp = document.createElement("input");
    inp.type = "file"; inp.accept = ".json,application/json"; inp.className = "pr-native-file";
    inp.addEventListener("change", function () { var f = inp.files && inp.files[0]; inp.value = ""; if (f) scwin.importTemplate(f); });
    document.body.appendChild(inp);
    scwin.importInput = inp;
};
scwin.btn_tImport_onclick = function () { scwin.importInput.click(); };
scwin.importTemplate = function (f) {
    if (f.size > 1024 * 1024) { scwin.toast("File mẫu tối đa 1 MB.", "warning"); return; }
    var fd = new FormData();
    fd.append("file", f);
    btn_tImport.addClass("is-busy");
    scwin.xhr("POST", scwin.TPL_API + "/import", { body: fd }).then(function (t) {
        scwin.toast("Đã import mẫu " + t.templateName + ".", "success");
        scwin.loadTemplates();
    }).catch(function (err) { scwin.toast(err.message, "error"); })
      .then(function () { btn_tImport.removeClass("is-busy"); });
};

/* =====================================================================
 * HỘP NHẬP & HỘP XÁC NHẬN
 * ===================================================================== */
scwin.openAsk = function (o) {
    scwin.ask = o;
    tbx_askTitle.setValue(o.title); tbx_askLabel.setValue(o.label);
    ibx_ask.setValue(o.value || ""); btn_askOk.setValue(o.okText || "Đồng ý");
    scwin.show(tbx_askErr, false);
    scwin.open.ask = true; grp_askMask.addClass("is-open");
    setTimeout(function () { try { ibx_ask.focus(); } catch (e) { } }, 100);
};
scwin.closeAsk = function () { scwin.open.ask = false; grp_askMask.removeClass("is-open"); };
scwin.btn_askCancel_onclick = scwin.closeAsk;
scwin.btn_askOk_onclick = function () {
    var o = scwin.ask;
    btn_askOk.addClass("is-busy");
    Promise.resolve(o.onOk(scwin.trim(ibx_ask.getValue()))).then(scwin.closeAsk)
        .catch(function (err) { tbx_askErr.setValue(err.message); scwin.show(tbx_askErr, true); })
        .then(function () { btn_askOk.removeClass("is-busy"); });
};
scwin.openConfirm = function (o) {
    scwin.cfm = o;
    tbx_cfmTitle.setValue(o.title); tbx_cfmMsg.setValue(o.message || "");
    btn_cfmOk.setValue(o.okText || "Đồng ý");
    scwin.toggleClass(btn_cfmOk, "pr-btn--danger", !!o.danger);
    scwin.toggleClass(btn_cfmOk, "pr-btn--primary", !o.danger);
    scwin.toggleClass(grp_cfmModal, "is-danger", !!o.danger);
    scwin.open.confirm = true; grp_cfmMask.addClass("is-open");
};
scwin.closeConfirm = function () { scwin.open.confirm = false; grp_cfmMask.removeClass("is-open"); };
scwin.btn_cfmCancel_onclick = scwin.closeConfirm;
scwin.btn_cfmOk_onclick = function () { var o = scwin.cfm; scwin.closeConfirm(); if (o && o.onOk) o.onOk(); };

scwin.onGlobalKeydown = function (e) {
    if (e.key !== "Escape") return;
    if (scwin.open.confirm) scwin.closeConfirm();
    else if (scwin.open.ask) scwin.closeAsk();
    else if (scwin.open.pv) scwin.closePv();
    else if (scwin.open.job) scwin.closeJob();
};

